function bernoulli(rho, v1, v2, p1, h1, h2){
  rho=+rho; v1=+v1; v2=+v2; p1=+p1; h1=+h1; h2=+h2;
  if([rho,v1,v2,p1,h1,h2].some(function(v){return isNaN(v);})) return {error:'请填满密度/两速度/压强/两高度'};
  var g=9.81;
  var p2 = p1 + 0.5*rho*(v1*v1 - v2*v2) + rho*g*(h1 - h2);
  return {p2:Math.round(p2*100)/100, rho:rho, note:'p₂ = p₁ + ½ρ(v₁²−v₂²) + ρg(h₁−h₂)（忽略损失）'};
}
var EXPORTS={bernoulli:bernoulli};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BernoulliForgePure = EXPORTS; }
